<?php require_once __DIR__.'/components.php';require_once __DIR__.'/purchase-pricing.php';$intent=one('SELECT * FROM shop_module_intents WHERE id=? AND customer_id=?',[(int)($_GET['id']??$_POST['intent_id']??0),user()['id']]);$p=null;$problem='';try{if(!$intent || !in_array($intent['state'],['selected','payment_pending'],true))throw new RuntimeException('Dieses Zusatzmodul ist nicht für eine neue Bestellung verfügbar.');$p=module_purchase_pricing(module_checkout_product($intent),(int)user()['id'],$_POST);}catch(RuntimeException $e){$problem=$e instanceof PDOException?'Die Modulauswahl konnte nicht geladen werden.':$e->getMessage();} ?>
<a class="back-link" href="/konto/produkte">← Meine Produkte</a><div class="page-heading"><div class="eyebrow">PAKET ERWEITERN</div><h1>Zusatzmodul abonnieren</h1></div><?php if(!$p): ?><div class="info-box"><?= e($problem) ?></div><?php else:$pricing=$p['_module_pricing'];$docs=checkout_documents_for($p);if($_SERVER['REQUEST_METHOD']==='GET' || ($_POST['action']??'')==='pricing_preview'){$_SESSION['checkout_key']=bin2hex(random_bytes(24));$_SESSION['checkout_offer']=module_component_offer($p);} ?>
<section class="panel form-panel"><h2><?= e($pricing['line']['label']) ?></h2><p><?= e(module_description([$pricing['line']])) ?></p><dl class="detail-list"><div><dt>Grundpaket</dt><dd><?= e($pricing['parent']['product_name']) ?> · <?= e($pricing['parent']['domain']) ?></dd></div><div><dt>Jetzt anteilig bis <?= date('d.m.Y H:i',$pricing['initial_until']) ?></dt><dd><?= money($pricing['initial']['gross_cents']) ?> inkl. 19 % MwSt.</dd></div><div><dt>Danach regelmäßig ab <?= date('d.m.Y',$pricing['initial_until']) ?></dt><dd><?= money($pricing['regular']['gross_cents']) ?> inkl. 19 % MwSt. / <?= cycle($p['billing']) ?></dd></div></dl><?php tax_summary($pricing['initial'],'once'); ?><?php if($p['price_cents']===0 && ($p['_purchase_pricing']['regular_net']??1)===0): ?><p>Durch deinen Gutschein vollständig ausgeglichen, ohne Geldfluss. Die Erweiterung wird kostenlos freigegeben.</p><?php elseif($p['billing']==='months24'): ?><p>Du bezahlst den anteiligen Zeitraum mit PayPal. Danach erhältst du alle 24 Monate eine neue Rechnung mit PayPal-Zahlungslink.</p><?php else: ?><p>Du bestätigst ein eigenes PayPal-Abo für dieses Zusatzmodul. Die erste anteilige Zahlung wird bei Freigabe fällig. Nach bestätigtem Zahlungseingang wird die Erweiterung aktiviert. Kündigung jederzeit zum Ende des bezahlten Zeitraums, ohne zusätzliche Mindestlaufzeit.</p><?php endif ?>
<form method="post" data-purchase-pricing-form><?= csrf() ?><input type="hidden" name="action" value="module_checkout"><input type="hidden" name="intent_id" value="<?= (int)$intent['id'] ?>"><input type="hidden" name="checkout_key" value="<?= e($_SESSION['checkout_key']) ?>"><?php if(empty($p['_purchase_pricing']['redemption_parent'])):purchase_pricing_fields($p,$_POST);else: ?><div class="info-box">Der in deiner Paketbestellung vereinbarte Rabatt ist hier bereits berücksichtigt.</div><?php endif ?><h3>Rechnungsanschrift</h3><div class="form-grid"><?php foreach(billing_fields() as $key=>[$caption,$autocomplete,$maximum]):$value=$_POST['billing'][$key]??(user()[$key]?:($key==='country'?'DE':''));if($key==='country'){billing_country_select('billing[country]',(string)$value,true);continue;} ?><label class="field"><span><?= e($caption) ?></span><input name="billing[<?= $key ?>]" autocomplete="<?= $autocomplete ?>" maxlength="<?= $maximum ?>" value="<?= e($value) ?>" <?= in_array($key,['address','postal_code','city'],true)?'required':'' ?>></label><?php endforeach ?></div>
<label class="checkbox-field"><input type="checkbox" name="terms" required><span>Ich akzeptiere die <a href="<?= e($docs['terms_url']) ?>" target="_blank" rel="noopener">Vertragsbedingungen</a> und habe die <a href="<?= e($docs['withdrawal_url']) ?>" target="_blank" rel="noopener">Widerrufsinformationen</a> gelesen.</span></label><label class="checkbox-field"><input type="checkbox" name="invoice_pdf" required><span>Rechnungen als PDF per E-Mail und im Kundenkonto erhalten.</span></label><label class="checkbox-field"><input type="checkbox" name="privacy" required><span>Die <a href="/impress.html#datenschutz" target="_blank" rel="noopener">Datenschutzhinweise</a> habe ich gelesen.</span></label><button class="button button-teal" data-pricing-checkout <?= checkout_ready($p)?'':'disabled' ?>><?= $p['price_cents']===0 && ($p['_purchase_pricing']['regular_net']??1)===0?'Kostenlos verbindlich bestellen':($p['billing']==='months24'?'Zahlungspflichtig mit PayPal bestellen':'Mit PayPal abonnieren') ?></button></form></section><?php endif ?>
